(4206990, 606272, 15711, '<td valign="top">What a gem. Looks just like a 50''s photo.</td>', 'What a gem. Looks just like a 50''s photo.', '2007-10-31 00:04:08.000000', NULL, 1),
(4206993, 606709, 15711, '<td valign="top">Bonnie and Clyde''s car. LOL  Love the retro feel.</td>', 'Bonnie and Clyde''s car. LOL  Love the retro feel.', '2007-10-31 00:05:22.000000', NULL, 1),
(4206999, 606757, 15711, '<td valign="top">That is lovely.  I love the tones.  The lean of the tree shows the years of the sea wind blowing. GREAT clouds.</td>', 'That is lovely.  I love the tones.  The lean of the tree shows the years of the sea wind blowing. GREAT clouds.', '2007-10-31 00:07:05.000000', NULL, 1),
(4207007, 606818, 15711, '<td valign="top">She is wonderful. Love her deep red coat. Lovely lighting and perspective.</td>', 'She is wonderful. Love her deep red coat. Lovely lighting and perspective.', '2007-10-31 00:08:11.000000', NULL, 1),
(4207021, 606633, 15711, '<td valign="top">How darling they are.  This is great.</td>', 'How darling they are.  This is great.', '2007-10-31 00:11:10.000000', NULL, 1),
