(4207065, 606552, 64446, '<td valign="top">Nice lines and composition.</td>', 'Nice lines and composition.', '2007-10-31 00:20:23.000000', NULL, 1),
(4207069, 606594, 85388, '<td valign="top">cool subject, but i wish the angle was just a bit different, and reveal more of the car</td>', 'cool subject, but i wish the angle was just a bit different, and reveal more of the car', '2007-10-31 00:21:01.000000', NULL, 1),
