(4207141, 605312, 68648, '<td valign="top">really interesting image, but how is this "something old"?  The model looks quite young....</td>', 'really interesting image, but how is this "something old"?  The model looks quite young....', '2007-10-31 00:33:43.000000', NULL, 1),
(4207160, 605839, 83313, '<td valign="top">Nice detail. The gold leaf on the sign stands out nicely.</td>', 'Nice detail. The gold leaf on the sign stands out nicely.', '2007-10-31 00:37:55.000000', NULL, 1),
(4207166, 606616, 83313, '<td valign="top">An ok macro shot, but nothing stands out. Perhaps some different lighting would have enhanced the texture  of it.</td>', 'An ok macro shot, but nothing stands out. Perhaps some different lighting would have enhanced the texture  of it.', '2007-10-31 00:39:07.000000', NULL, 1),
(4207177, 606209, 66398, '<td valign="top">I love this shot. Looks more like a kitten and not an old cat but I could be wrong. I love the lighting in this. It''s very different. (comment only-not voting).</td>', 'I love this shot. Looks more like a kitten and not an old cat but I could be wrong. I love the lighting in this. It''s very different. (comment only-not voting).', '2007-10-31 00:42:08.000000', NULL, 1),
(4207188, 606549, 70514, '<td valign="top">How eerie!  And just in time for Halloween....</td>', 'How eerie!  And just in time for Halloween....', '2007-10-31 00:44:03.000000', NULL, 1),
(4207189, 606107, 83313, '<td valign="top">I like the composition and interesting subject, but it is very pixelated. Is this a severe crop, or did you have some problems downsizing the image? The color is also very warm, it is clearly an evening shot. I would have adjusted the color balance a bit.</td>', 'I like the composition and interesting subject, but it is very pixelated. Is this a severe crop, or did you have some problems downsizing the image? The color is also very warm, it is clearly an evening shot. I would have adjusted the color balance a bit.', '2007-10-31 00:44:22.000000', NULL, 1),
(4207191, 606153, 83313, '<td valign="top">Just too centered.</td>', 'Just too centered.', '2007-10-31 00:44:54.000000', NULL, 1),
(4207203, 606360, 83313, '<td valign="top">Nice view. I like just the streak of strong yellow on the left.</td>', 'Nice view. I like just the streak of strong yellow on the left.', '2007-10-31 00:50:02.000000', NULL, 1),
(4207205, 606715, 83313, '<td valign="top">I like the treatment of this image. Looks a little bit like a former coworker.</td>', 'I like the treatment of this image. Looks a little bit like a former coworker.', '2007-10-31 00:50:49.000000', NULL, 1),
(4207208, 606776, 83313, '<td valign="top">Nice strong colors and a crisp image. I''m not sure I like the angle and the crop of it, though.</td>', 'Nice strong colors and a crisp image. I''m not sure I like the angle and the crop of it, though.', '2007-10-31 00:52:16.000000', NULL, 1),
(4207209, 606650, 83313, '<td valign="top">The angle keeps me looking for the rest of the image.</td>', 'The angle keeps me looking for the rest of the image.', '2007-10-31 00:52:47.000000', NULL, 1),
(4207212, 606251, 83313, '<td valign="top">Not quite crisp and clear enough in the shadows.</td>', 'Not quite crisp and clear enough in the shadows.', '2007-10-31 00:53:31.000000', NULL, 1),
(4207213, 606151, 83313, '<td valign="top">Nice texture and color.</td>', 'Nice texture and color.', '2007-10-31 00:54:00.000000', NULL, 1),
(4207216, 606583, 83313, '<td valign="top">How appropriate! Good job on this.</td>', 'How appropriate! Good job on this.', '2007-10-31 00:54:43.000000', NULL, 1),
(4207219, 605554, 83313, '<td valign="top">A good example of the usual effect of a flash working FOR you.</td>', 'A good example of the usual effect of a flash working FOR you.', '2007-10-31 00:55:40.000000', NULL, 1),
(4207241, 606812, 83375, '<td valign="top">A very intriguing submission... would have preferred to have eye contact though.</td>', 'A very intriguing submission... would have preferred to have eye contact though.', '2007-10-31 01:09:16.000000', NULL, 1),
(4207246, 605282, 83375, '<td valign="top">Well composed and good detail level.</td>', 'Well composed and good detail level.', '2007-10-31 01:10:11.000000', NULL, 1),
(4207249, 606722, 83375, '<td valign="top">Ok, maybe it''s cuz I''m Sox fan or maybe it''s just because I like good photography, but that''s awesome.</td>', 'Ok, maybe it''s cuz I''m Sox fan or maybe it''s just because I like good photography, but that''s awesome.', '2007-10-31 01:11:28.000000', NULL, 1),
(4207258, 606397, 83375, '<td valign="top">Cool tree, the colors seem off to me though..lacking vibrance.</td>', 'Cool tree, the colors seem off to me though..lacking vibrance.', '2007-10-31 01:13:24.000000', NULL, 1),
(4207302, 605006, 83375, '<td valign="top">I think this is REALLY stretching the bounds of the challenge.</td>', 'I think this is REALLY stretching the bounds of the challenge.', '2007-10-31 01:30:17.000000', NULL, 1),
(4207308, 606765, 64670, '<td valign="top">Great image, descriptive and good tones.</td>', 'Great image, descriptive and good tones.', '2007-10-31 01:31:58.000000', NULL, 1),
(4207312, 606633, 64670, '<td valign="top">Just priceless - LOVE the bond between the two - you''re very fortunate to have been given the opportunity to capture such an image.</td>', 'Just priceless - LOVE the bond between the two - you''re very fortunate to have been given the opportunity to capture such an image.', '2007-10-31 01:32:59.000000', NULL, 1),
(4207314, 606550, 64670, '<td valign="top">Very clever spotting - great colours.</td>', 'Very clever spotting - great colours.', '2007-10-31 01:33:20.000000', NULL, 1),
(4207316, 606656, 64670, '<td valign="top">Lovely hues and tones, excellent depth of field.  Interesting take on the subject.</td>', 'Lovely hues and tones, excellent depth of field.  Interesting take on the subject.', '2007-10-31 01:33:49.000000', NULL, 1),
(4207318, 606398, 64670, '<td valign="top">Not a very interesting or inspiring image.  Lacks good sharp focus or interesting perspective.</td>', 'Not a very interesting or inspiring image.  Lacks good sharp focus or interesting perspective.', '2007-10-31 01:34:31.000000', NULL, 1),
(4207321, 606284, 64670, '<td valign="top">Wonderful take on the challenge - good depth of field.</td>', 'Wonderful take on the challenge - good depth of field.', '2007-10-31 01:35:15.000000', NULL, 1),
(4207337, 606578, 64670, '<td valign="top">Lovely take on the challenge.  Wonderful lighting.</td>', 'Lovely take on the challenge.  Wonderful lighting.', '2007-10-31 01:37:27.000000', NULL, 1),
(4207339, 606122, 64670, '<td valign="top">Excellent subject, fantastic perspective.  Clear and sharp.  Obviously the harsh lighting in challenging to you which made it all lacking contrast.</td>', 'Excellent subject, fantastic perspective.  Clear and sharp.  Obviously the harsh lighting in challenging to you which made it all lacking contrast.', '2007-10-31 01:38:22.000000', NULL, 1),
(4207344, 606833, 64670, '<td valign="top">Great subject.  Curious crop though.  Would like to have seen the whole vessel and not have the bits cut off it as is.  Alternatively a tighter crop say removing almost 1/3 of the left and 1/3 off the top may have worked nicely.</td>', 'Great subject.  Curious crop though.  Would like to have seen the whole vessel and not have the bits cut off it as is.  Alternatively a tighter crop say removing almost 1/3 of the left and 1/3 off the top may have worked nicely.', '2007-10-31 01:39:54.000000', NULL, 1),
(4207350, 606808, 64670, '<td valign="top">Wonderful subject, perspective and idea.  I really like the tones and gentleness.  Great post processing.</td>', 'Wonderful subject, perspective and idea.  I really like the tones and gentleness.  Great post processing.', '2007-10-31 01:40:46.000000', NULL, 1),
(4207355, 606544, 64670, '<td valign="top">Lovely fluffy stuff, but then I realise it something going off, which makes it sort of gross.  Can''t tell really what it is, I''m guessing a strawberry.  Lovely pinks/reds.  Otherwise not appetising - GRIN!</td>', 'Lovely fluffy stuff, but then I realise it something going off, which makes it sort of gross.  Can''t tell really what it is, I''m guessing a strawberry.  Lovely pinks/reds.  Otherwise not appetising - GRIN!', '2007-10-31 01:42:15.000000', NULL, 1),
(4207358, 604837, 64670, '<td valign="top">Interesting idea - they remind me somewhat of cigars.</td>', 'Interesting idea - they remind me somewhat of cigars.', '2007-10-31 01:42:55.000000', NULL, 1),
(4207365, 606763, 64670, '<td valign="top">Just lovely perspective, clear subject and great depth of field and flow behind.  The image would do with a bit of oomph in the selective colours - greens, blacks etc (if you use photoshop.)</td>', 'Just lovely perspective, clear subject and great depth of field and flow behind.  The image would do with a bit of oomph in the selective colours - greens, blacks etc (if you use photoshop.)', '2007-10-31 01:43:58.000000', NULL, 1),
(4207369, 606189, 64670, '<td valign="top">Wonderful perspective - excellent use of fish eye.  Don''t fancy the white border, don''t think it needed it.  May have benefitted from so selective colour saturation.</td>', 'Wonderful perspective - excellent use of fish eye.  Don''t fancy the white border, don''t think it needed it.  May have benefitted from so selective colour saturation.', '2007-10-31 01:44:50.000000', NULL, 1),
(4207371, 605979, 64670, '<td valign="top">Interesting subject, but the handling of it leaves it rather dull.</td>', 'Interesting subject, but the handling of it leaves it rather dull.', '2007-10-31 01:45:27.000000', NULL, 1),
(4207373, 606669, 64670, '<td valign="top">Rather nice in it''s simplicity. I think a tweaking with selective colours to add saturation would have worked a treat.</td>', 'Rather nice in it''s simplicity. I think a tweaking with selective colours to add saturation would have worked a treat.', '2007-10-31 01:46:04.000000', NULL, 1),
(4207375, 606640, 64670, '<td valign="top">Wonderful subject and location.  However it all falls a bit flat due to lighting.</td>', 'Wonderful subject and location.  However it all falls a bit flat due to lighting.', '2007-10-31 01:46:41.000000', NULL, 1),
(4207377, 606660, 64670, '<td valign="top">This is absolutely WONDERFUL!  The sharpness, the tones, just WONDERFUL!  10!</td>', 'This is absolutely WONDERFUL!  The sharpness, the tones, just WONDERFUL!  10!', '2007-10-31 01:47:13.000000', NULL, 1),
(4207380, 605637, 64670, '<td valign="top">Aren''t we all - GRIN!   The idea is good, subject is good and perspective and crop are good.  The lighting has let you down severly which is a shame.  You''ve lost the tones - wish it had been different, I really like it otherwise.</td>', 'Aren''t we all - GRIN!   The idea is good, subject is good and perspective and crop are good.  The lighting has let you down severly which is a shame.  You''ve lost the tones - wish it had been different, I really like it otherwise.', '2007-10-31 01:48:45.000000', NULL, 1),
(4207381, 606213, 64670, '<td valign="top">The harsh lighting does little for the image.  Your ''special'' leaf barely stand out from the litter.</td>', 'The harsh lighting does little for the image.  Your ''special'' leaf barely stand out from the litter.', '2007-10-31 01:49:32.000000', NULL, 1),
(4207383, 605731, 64670, '<td valign="top">Great location and subject.  The date above the door is great for the challenge, but the lighting is too harsh.</td>', 'Great location and subject.  The date above the door is great for the challenge, but the lighting is too harsh.', '2007-10-31 01:50:35.000000', NULL, 1),
(4207387, 606802, 64670, '<td valign="top">Cool location.  It looks like you''ve taken it while driving past.  I think a wander about the building and taking a crisper clearer more cropped image may have worked much better.</td>', 'Cool location.  It looks like you''ve taken it while driving past.  I think a wander about the building and taking a crisper clearer more cropped image may have worked much better.', '2007-10-31 01:51:36.000000', NULL, 1),
(4207388, 606636, 64670, '<td valign="top">Excellent perspective - love the location.  The lighting lets the image down.  It should be more drab I think to create ''mood''.</td>', 'Excellent perspective - love the location.  The lighting lets the image down.  It should be more drab I think to create ''mood''.', '2007-10-31 01:52:16.000000', NULL, 1),
(4207389, 605738, 64670, '<td valign="top">Great subject, but the lighting detracts severly from how interesting it could have been.</td>', 'Great subject, but the lighting detracts severly from how interesting it could have been.', '2007-10-31 01:53:00.000000', NULL, 1),
(4207393, 606760, 64670, '<td valign="top">Fantastically great subject and awesome pose, just SO disappointed by the lack of clarity and sharpness.</td>', 'Fantastically great subject and awesome pose, just SO disappointed by the lack of clarity and sharpness.', '2007-10-31 01:53:53.000000', NULL, 1),
(4207395, 606593, 64670, '<td valign="top">Don''t really know what it is, but I trust you, it looks old.  The image is very harsh on my eyes.  It looks to be VERY harsh lighting and then too much sharpening.</td>', 'Don''t really know what it is, but I trust you, it looks old.  The image is very harsh on my eyes.  It looks to be VERY harsh lighting and then too much sharpening.', '2007-10-31 01:54:57.000000', NULL, 1),
(4207398, 604794, 64670, '<td valign="top">Brilliant!  Love the idea, subject, perspective and texture -great tones and hues - just GREAT!</td>', 'Brilliant!  Love the idea, subject, perspective and texture -great tones and hues - just GREAT!', '2007-10-31 01:55:38.000000', NULL, 1),
(4207400, 605315, 64670, '<td valign="top">I think the location is great, but for this challenge the inclusion of modern artifacts looses the spirit for me.  I''m really not fond of the juxtaposition of the woman on the phone, nor the sign of to the right.  Also the poles in the planters look horrid.  I think another point of view of the building would have been best.</td>', 'I think the location is great, but for this challenge the inclusion of modern artifacts looses the spirit for me.  I''m really not fond of the juxtaposition of the woman on the phone, nor the sign of to the right.  Also the poles in the planters look horrid.  I think another point of view of the building would have been best.', '2007-10-31 01:57:20.000000', NULL, 1),
(4207404, 606650, 64670, '<td valign="top">Looks like a funky building.  The lighting seemed to be against you and I wonder if that was the reason behind your unusual cropping choice?</td>', 'Looks like a funky building.  The lighting seemed to be against you and I wonder if that was the reason behind your unusual cropping choice?', '2007-10-31 01:58:11.000000', NULL, 1),
(4207408, 605236, 64670, '<td valign="top">Beautiful subject, great face.  Unfortunately the lighting is against you and it appears you may have rushed taking the image.</td>', 'Beautiful subject, great face.  Unfortunately the lighting is against you and it appears you may have rushed taking the image.', '2007-10-31 02:01:08.000000', NULL, 1),
(4207415, 605312, 64670, '<td valign="top">Interesting nude and shiny too.  The crop is too extreme in my opinion.<br/> <br/>In addition I can see that you''re trying to come from left of centre of the topic, but I feel this does not really meet the spirit of the challenge as you''re not showing me anything ''old''.</td>', 'Interesting nude and shiny too.  The crop is too extreme in my opinion. In addition I can see that you''re trying to come from left of centre of the topic, but I feel this does not really meet the spirit of the challenge as you''re not showing me anything ''old''.', '2007-10-31 02:03:41.000000', NULL, 1),
(4207417, 605792, 64670, '<td valign="top">The image is not working.  The lighting and position mean that we cannot clearly see the features of this ''dog''.  It just looks like a blob with the smallest suggestion of an eye and tongue.   Lack of clarity really means the subject is lost.</td>', 'The image is not working.  The lighting and position mean that we cannot clearly see the features of this ''dog''.  It just looks like a blob with the smallest suggestion of an eye and tongue.   Lack of clarity really means the subject is lost.', '2007-10-31 02:05:24.000000', NULL, 1),
(4207421, 606201, 64670, '<td valign="top">Sensational photo - I just love it.  But I must say it''s stretching it for the challenge.<br/> <br/>As in image I think it ROCKS!  Love the lighting and B&amp;W.</td>', 'Sensational photo - I just love it.  But I must say it''s stretching it for the challenge. As in image I think it ROCKS!  Love the lighting and B&W.', '2007-10-31 02:06:13.000000', NULL, 1),
(4207422, 606751, 64670, '<td valign="top">Great subject.  A bit more brightness would have worked for me.</td>', 'Great subject.  A bit more brightness would have worked for me.', '2007-10-31 02:06:50.000000', NULL, 1),
(4207430, 605520, 64670, '<td valign="top">So Australian!</td>', 'So Australian!', '2007-10-31 02:12:31.000000', NULL, 1),
(4207449, 606751, 28097, '<td valign="top">geniune and creative.. good job</td>', 'geniune and creative.. good job', '2007-10-31 02:23:16.000000', NULL, 1),
(4207510, 605792, 32602, '<td valign="top">needs some more detail in the face but black dogs/cats/furry animals can be difficult to shoot</td>', 'needs some more detail in the face but black dogs/cats/furry animals can be difficult to shoot', '2007-10-31 03:53:52.000000', NULL, 1),
(4207512, 606242, 32602, '<td valign="top">that is a really cool chair, cool composition and great colour</td>', 'that is a really cool chair, cool composition and great colour', '2007-10-31 03:55:31.000000', NULL, 1),
(4207514, 606077, 32602, '<td valign="top">lovely</td>', 'lovely', '2007-10-31 03:56:15.000000', NULL, 1),
(4207534, 605366, 48086, '<td valign="top">nice scene, but has a washed out look to it, too much shadow/highlight?</td>', 'nice scene, but has a washed out look to it, too much shadow/highlight?', '2007-10-31 04:34:43.000000', NULL, 1),
(4207540, 605556, 42171, '<td valign="top">Snow! At this time of year!<br/> <br/>Nice capture though - Poor old truck...</td>', 'Snow! At this time of year! Nice capture though - Poor old truck...', '2007-10-31 04:43:22.000000', NULL, 1),
(4207543, 605468, 48086, '<td valign="top">very nice and creative, little nag is the bottom is a bit too tight cropped.</td>', 'very nice and creative, little nag is the bottom is a bit too tight cropped.', '2007-10-31 04:48:16.000000', NULL, 1),
(4207545, 606519, 48086, '<td valign="top">some strange halo around the watch, like the colors and subject</td>', 'some strange halo around the watch, like the colors and subject', '2007-10-31 04:49:36.000000', NULL, 1),
(4207547, 606722, 48086, '<td valign="top">nice shot, shame about the out of focus top left dof, it distracts. Colors seem a bit too muted for my taste</td>', 'nice shot, shame about the out of focus top left dof, it distracts. Colors seem a bit too muted for my taste', '2007-10-31 04:50:28.000000', NULL, 1),
