(4207555, 606509, 48086, '<td valign="top">the bottom right subject is competing too much with the main interest of the picture, other than that, good bw conversion and nice toning</td>', 'the bottom right subject is competing too much with the main interest of the picture, other than that, good bw conversion and nice toning', '2007-10-31 04:58:35.000000', NULL, 1),
(4207557, 606811, 48086, '<td valign="top">nice scene and colors, but somehow lacks sharpness. top right white spot is also a bit distracting. This scene has a lot of potential, I would go back and shoot some more with different skies, seasons</td>', 'nice scene and colors, but somehow lacks sharpness. top right white spot is also a bit distracting. This scene has a lot of potential, I would go back and shoot some more with different skies, seasons', '2007-10-31 05:00:35.000000', NULL, 1),
(4207559, 604468, 48086, '<td valign="top">great colors and subject. would like less dof on the foreground, and crop a bit more on the left side.</td>', 'great colors and subject. would like less dof on the foreground, and crop a bit more on the left side.', '2007-10-31 05:02:03.000000', NULL, 1),
(4207560, 606544, 48086, '<td valign="top">only two? more like two weeks :)</td>', 'only two? more like two weeks :)', '2007-10-31 05:03:38.000000', NULL, 1),
(4207568, 605655, 48086, '<td valign="top">a bit overworked symbolism for my taste. shot would be great without the strongly reflecting mirror/table. Now it looks like her left arm is amputated. Good bw conversion though, but there are some artefacts on the left arm. The top of her head is missing due to crop.</td>', 'a bit overworked symbolism for my taste. shot would be great without the strongly reflecting mirror/table. Now it looks like her left arm is amputated. Good bw conversion though, but there are some artefacts on the left arm. The top of her head is missing due to crop.', '2007-10-31 05:10:44.000000', NULL, 1),
(4207574, 606392, 48086, '<td valign="top">lacks sharpness, and the light is too harsh. would reshoot with better condition as the subject is interesting enough</td>', 'lacks sharpness, and the light is too harsh. would reshoot with better condition as the subject is interesting enough', '2007-10-31 05:15:21.000000', NULL, 1),
