(4208343, 605312, 10665, '<td valign="top">Not a typical take on Old.  I like the pose but I find the tight crop on the sides makes the figure seem trapped.</td>', 'Not a typical take on Old.  I like the pose but I find the tight crop on the sides makes the figure seem trapped.', '2007-10-31 11:30:28.000000', NULL, 1),
(4208346, 606272, 86016, '<td valign="top">What''s that shiny thing in the back??? otherwise a lovely pic.</td>', 'What''s that shiny thing in the back??? otherwise a lovely pic.', '2007-10-31 11:30:40.000000', NULL, 1),
(4208358, 606788, 10665, '<td valign="top">It''s a wonderful old tree.  The lighting seems a bit harsh, mid-day?  Late afternoon would be an ideal time to shoot this subject.</td>', 'It''s a wonderful old tree.  The lighting seems a bit harsh, mid-day?  Late afternoon would be an ideal time to shoot this subject.', '2007-10-31 11:37:12.000000', NULL, 1),
(4208360, 605251, 10665, '<td valign="top">I like the lighting on this shot, but would have prefered if some of the foreground writing was in sharper focus.</td>', 'I like the lighting on this shot, but would have prefered if some of the foreground writing was in sharper focus.', '2007-10-31 11:38:30.000000', NULL, 1),
(4208364, 606709, 10665, '<td valign="top">Ir seems a bit too dark but I like that there is only a slight pop of color in the sign.  I would have prefered if the wheel was not amputated.</td>', 'Ir seems a bit too dark but I like that there is only a slight pop of color in the sign.  I would have prefered if the wheel was not amputated.', '2007-10-31 11:40:29.000000', NULL, 1),
(4208367, 606501, 10665, '<td valign="top">The lighting is very harsh and I think the composition would have been helped if you have taken the shot from a lower vantage point</td>', 'The lighting is very harsh and I think the composition would have been helped if you have taken the shot from a lower vantage point', '2007-10-31 11:42:01.000000', NULL, 1),
(4208369, 606737, 10665, '<td valign="top">I like the feel of this shot but would have prefered if the door frame had been straightened</td>', 'I like the feel of this shot but would have prefered if the door frame had been straightened', '2007-10-31 11:43:06.000000', NULL, 1),
(4208375, 606158, 49954, '<td valign="top">Cool photo and rocks, but since the earth is only about 10,000 years old (per scientific evidence), your title is left wanting.</td>', 'Cool photo and rocks, but since the earth is only about 10,000 years old (per scientific evidence), your title is left wanting.', '2007-10-31 11:46:09.000000', NULL, 1),
(4208384, 606699, 78110, '<td valign="top">hehe..good one :D</td>', 'hehe..good one :D', '2007-10-31 11:48:11.000000', NULL, 1),
(4208402, 606709, 78110, '<td valign="top">good photo, just composition is not my taste..</td>', 'good photo, just composition is not my taste..', '2007-10-31 11:56:39.000000', NULL, 1),
(4208442, 606203, 85887, '<td valign="top">I''m not sure if you did it for affect, but it looks to be a bit over-exposed..<br/>But if it was for the ''old photo'' affect, it doesn''t look completely right.. good try though..</td>', 'I''m not sure if you did it for affect, but it looks to be a bit over-exposed..But if it was for the ''old photo'' affect, it doesn''t look completely right.. good try though..', '2007-10-31 12:11:38.000000', NULL, 1),
