(4208533, 604463, 56275, '<td valign="top">Very old feel to this photo. I wonder how an even tighter crop would do, or maybe even pulling away a little more to show more of the stem.</td>', 'Very old feel to this photo. I wonder how an even tighter crop would do, or maybe even pulling away a little more to show more of the stem.', '2007-10-31 12:45:25.000000', NULL, 1),
(4208538, 606319, 56275, '<td valign="top">Looks a little out of focus. I''d suggest getting a clear focus on the hands of the watch, since that''s what my eyes are directed to.</td>', 'Looks a little out of focus. I''d suggest getting a clear focus on the hands of the watch, since that''s what my eyes are directed to.', '2007-10-31 12:46:40.000000', NULL, 1),
(4208543, 606285, 56275, '<td valign="top">Very crisp and clear, but the straight-down angle isn''t very interesting.</td>', 'Very crisp and clear, but the straight-down angle isn''t very interesting.', '2007-10-31 12:47:26.000000', NULL, 1),
(4208552, 606550, 56275, '<td valign="top">Not sure what I''m looking at.. Interesting colors and textures.. but the subject is unclear.</td>', 'Not sure what I''m looking at.. Interesting colors and textures.. but the subject is unclear.', '2007-10-31 12:49:50.000000', NULL, 1),
