(4218908, 606667, 79720, '<td valign="top">"Dying"</td>', '"Dying"', '2007-11-03 19:57:05.000000', NULL, 1),
(4219109, 606419, 85383, '<td valign="top">Looks out of focus....is it supposed to be soft focus?</td>', 'Looks out of focus....is it supposed to be soft focus?', '2007-11-03 21:46:38.000000', NULL, 1),
(4219110, 606521, 85383, '<td valign="top">Focus is odd; try this at a different time of day. Lighting is a little harsh</td>', 'Focus is odd; try this at a different time of day. Lighting is a little harsh', '2007-11-03 21:48:37.000000', NULL, 1),
(4219113, 605730, 85383, '<td valign="top">What is going on in this photo? What is the blank area? What is the orange area at the top. It''s just very odd.</td>', 'What is going on in this photo? What is the blank area? What is the orange area at the top. It''s just very odd.', '2007-11-03 21:49:16.000000', NULL, 1),
(4219117, 606772, 85383, '<td valign="top">underexposed</td>', 'underexposed', '2007-11-03 21:50:39.000000', NULL, 1),
(4219119, 605006, 85383, '<td valign="top">What on earth? This is just weird.</td>', 'What on earth? This is just weird.', '2007-11-03 21:51:06.000000', NULL, 1),
(4219121, 605792, 85383, '<td valign="top">out of focus, dog is unerexposed</td>', 'out of focus, dog is unerexposed', '2007-11-03 21:51:30.000000', NULL, 1),
(4219124, 606717, 85383, '<td valign="top">too much emphasis is on the people and not the cafe</td>', 'too much emphasis is on the people and not the cafe', '2007-11-03 21:52:05.000000', NULL, 1),
(4219126, 605694, 85383, '<td valign="top">underexposed</td>', 'underexposed', '2007-11-03 21:52:24.000000', NULL, 1),
(4219131, 606398, 85383, '<td valign="top">I like the concept, but the composition is boring.</td>', 'I like the concept, but the composition is boring.', '2007-11-03 21:53:28.000000', NULL, 1),
(4219289, 606614, 164, '<td valign="top">odd</td>', 'odd', '2007-11-03 23:03:06.000000', NULL, 1),
(4219601, 606760, 85155, '<td valign="top">Those are some nice horns.  Great shot here.</td>', 'Those are some nice horns.  Great shot here.', '2007-11-04 01:43:19.000000', NULL, 1),
(4219602, 605524, 85155, '<td valign="top">I wish this was on a little bit of an angle, the straight row isn''t as interesting.  Great idea though, nice lighting.</td>', 'I wish this was on a little bit of an angle, the straight row isn''t as interesting.  Great idea though, nice lighting.', '2007-11-04 01:43:54.000000', NULL, 1),
(4219603, 605321, 85155, '<td valign="top">I like the b&amp;w to set the mood.  This would be much better with a really old guy, some wrinkles showing, but I still think you have done well with this shot.</td>', 'I like the b&w to set the mood.  This would be much better with a really old guy, some wrinkles showing, but I still think you have done well with this shot.', '2007-11-04 01:44:42.000000', NULL, 1),
(4219604, 606397, 85155, '<td valign="top">Too bad there are all those posts around the tree, they really take away from the picture, but there isn''t much you could have done about that.  I wish there was some contrast in color here, everything seems to be the same color.</td>', 'Too bad there are all those posts around the tree, they really take away from the picture, but there isn''t much you could have done about that.  I wish there was some contrast in color here, everything seems to be the same color.', '2007-11-04 01:45:34.000000', NULL, 1),
(4219607, 605811, 85155, '<td valign="top">I still can''t really tell what this is after seeing it for a while now.  Also, I don''t think the ring around the moon is helping, if you have a uv filter on, that may be causing it.</td>', 'I still can''t really tell what this is after seeing it for a while now.  Also, I don''t think the ring around the moon is helping, if you have a uv filter on, that may be causing it.', '2007-11-04 01:46:20.000000', NULL, 1),
(4219608, 606549, 85155, '<td valign="top">The tree is blocking too much of the church here.  I think we need to see more of the building, rather than more of the tree.</td>', 'The tree is blocking too much of the church here.  I think we need to see more of the building, rather than more of the tree.', '2007-11-04 01:46:46.000000', NULL, 1),
(4219611, 605255, 85155, '<td valign="top">I like the chipping paint, and the rust.  I think the brick, that is only in the corner, doesn''t help with the picture, it just doesn''t fit.  Nice idea.</td>', 'I like the chipping paint, and the rust.  I think the brick, that is only in the corner, doesn''t help with the picture, it just doesn''t fit.  Nice idea.', '2007-11-04 01:47:21.000000', NULL, 1),
(4219614, 606718, 85155, '<td valign="top">What is Acme No. 5?  I guess I just don''t know, I can tell it is old by the label though.  Nice b&amp;w conversion.</td>', 'What is Acme No. 5?  I guess I just don''t know, I can tell it is old by the label though.  Nice b&w conversion.', '2007-11-04 01:47:53.000000', NULL, 1),
(4219615, 605015, 85155, '<td valign="top">I like the old building feel.</td>', 'I like the old building feel.', '2007-11-04 01:48:17.000000', NULL, 1),
(4219617, 605758, 85155, '<td valign="top">This subject just isn''t catching my eye.  It isn''t a poor shot, just not interesting to me.</td>', 'This subject just isn''t catching my eye.  It isn''t a poor shot, just not interesting to me.', '2007-11-04 01:48:53.000000', NULL, 1),
(4219619, 606646, 85155, '<td valign="top">I really like the boots, but I don''t like the background, they really take away from the picture.  My eye keeps going to the different colored slats, rather that the boots.  Get a different background and I think this is a better shot.</td>', 'I really like the boots, but I don''t like the background, they really take away from the picture.  My eye keeps going to the different colored slats, rather that the boots.  Get a different background and I think this is a better shot.', '2007-11-04 01:49:41.000000', NULL, 1),
(4219620, 605324, 85155, '<td valign="top">I am having a hard time telling what this even is.  There is just way too much graffiti, it is too busy for me.</td>', 'I am having a hard time telling what this even is.  There is just way too much graffiti, it is too busy for me.', '2007-11-04 01:50:23.000000', NULL, 1),
(4219622, 604794, 85155, '<td valign="top">I really like the conversion here.  This is a great idea, I get the old feel without help from the title.  I also think the old scratched up table helps out here.  Nicely done.  Try taking this without the gloves right on top of each other and see what it looks like, I''m not sure it will help, but maybe check it out.</td>', 'I really like the conversion here.  This is a great idea, I get the old feel without help from the title.  I also think the old scratched up table helps out here.  Nicely done.  Try taking this without the gloves right on top of each other and see what it looks like, I''m not sure it will help, but maybe check it out.', '2007-11-04 01:51:28.000000', NULL, 1),
(4219624, 606698, 85155, '<td valign="top">I like the lines formed by the boards throughout the picture.</td>', 'I like the lines formed by the boards throughout the picture.', '2007-11-04 01:51:56.000000', NULL, 1),
(4219625, 606289, 85155, '<td valign="top">I wish the right of the car wasn''t cut off in the picture.  Also if the purple was standing out more I think this would be a little better.</td>', 'I wish the right of the car wasn''t cut off in the picture.  Also if the purple was standing out more I think this would be a little better.', '2007-11-04 01:52:30.000000', NULL, 1),
(4219630, 606713, 85155, '<td valign="top">Other than you telling me what the church is, and the year it was built, this is just like any other chapel out there, not necessarily old, without the help from the title.  I like the colors in the sky, I wish the horizon wasn''t right in the middle of the shot though.  And I wish I could see more of the church, rather than just the steeple, the bottom of the shot is just too dark.</td>', 'Other than you telling me what the church is, and the year it was built, this is just like any other chapel out there, not necessarily old, without the help from the title.  I like the colors in the sky, I wish the horizon wasn''t right in the middle of the shot though.  And I wish I could see more of the church, rather than just the steeple, the bottom of the shot is just too dark.', '2007-11-04 01:53:44.000000', NULL, 1),
(4219632, 606431, 85155, '<td valign="top">I think the majority of this shot is just too dark.</td>', 'I think the majority of this shot is just too dark.', '2007-11-04 01:54:12.000000', NULL, 1),
(4219634, 606189, 85155, '<td valign="top">This picture leads me to the ceiling, I don''t miss the gallery, and if you didn''t tell me I was supposed to be looking for a man, I wouldn''t have even seen him.  If you want the gallery to be the subject, make it the subject.</td>', 'This picture leads me to the ceiling, I don''t miss the gallery, and if you didn''t tell me I was supposed to be looking for a man, I wouldn''t have even seen him.  If you want the gallery to be the subject, make it the subject.', '2007-11-04 01:55:05.000000', NULL, 1),
(4219638, 606722, 85155, '<td valign="top">I really like this shot, nice and simple, I don''t need the title''s help to know it fits in the theme, and the background is a great match with the ball.  This is a nice change to a lot of the pictures I have been seeing.</td>', 'I really like this shot, nice and simple, I don''t need the title''s help to know it fits in the theme, and the background is a great match with the ball.  This is a nice change to a lot of the pictures I have been seeing.', '2007-11-04 01:55:49.000000', NULL, 1),
(4219640, 606398, 85155, '<td valign="top">The angle of this and the composition isn''t really very interesting.  Try backing out a little bit so we can get more of the camera, I think it is just too tight.</td>', 'The angle of this and the composition isn''t really very interesting.  Try backing out a little bit so we can get more of the camera, I think it is just too tight.', '2007-11-04 01:56:33.000000', NULL, 1),
(4219642, 606660, 85155, '<td valign="top">There it is, the first old shoe shot, I have been waiting for this.  Nicely done here, especially with the conversion.  I think it would be nice to see the whole shoe though, rather than cutting out the toe, and the other side of it.  I think this is an overall nice shot.</td>', 'There it is, the first old shoe shot, I have been waiting for this.  Nicely done here, especially with the conversion.  I think it would be nice to see the whole shoe though, rather than cutting out the toe, and the other side of it.  I think this is an overall nice shot.', '2007-11-04 01:57:25.000000', NULL, 1),
(4219644, 606596, 85155, '<td valign="top">I don''t like the color of the sky in this shot, and the smog blocks out that other tower too much.  I also think it would be better without the guy standing there, try to take this when nobody is in your way.</td>', 'I don''t like the color of the sky in this shot, and the smog blocks out that other tower too much.  I also think it would be better without the guy standing there, try to take this when nobody is in your way.', '2007-11-04 01:58:07.000000', NULL, 1),
(4219646, 606835, 85155, '<td valign="top">Now that is an old trailer.  I think you captured the theme really well, but it just isn''t an interesting subject to me.</td>', 'Now that is an old trailer.  I think you captured the theme really well, but it just isn''t an interesting subject to me.', '2007-11-04 01:58:35.000000', NULL, 1),
(4219649, 605619, 85155, '<td valign="top">This is my favorite old building style shot so far.  I like how the handle isn''t even on right, and the colors in the door are really nice.  Try coming at this from an angle rather than the straight on shot and see if it adds interest.</td>', 'This is my favorite old building style shot so far.  I like how the handle isn''t even on right, and the colors in the door are really nice.  Try coming at this from an angle rather than the straight on shot and see if it adds interest.', '2007-11-04 01:59:28.000000', NULL, 1),
(4219651, 605828, 85155, '<td valign="top">Did you mean abode?  Nice shot.</td>', 'Did you mean abode?  Nice shot.', '2007-11-04 01:00:24.000000', NULL, 1),
(4219953, 605255, 74821, '<td valign="top">For me this image suffers from a little over exposure.</td>', 'For me this image suffers from a little over exposure.', '2007-11-04 07:29:14.000000', NULL, 1),
(4220101, 606158, 73250, '<td valign="top">Those are the coolest looking stones!! Like the concept.</td>', 'Those are the coolest looking stones!! Like the concept.', '2007-11-04 09:59:23.000000', NULL, 1),
(4220102, 606614, 73250, '<td valign="top">I don''t think she''s going to get very far! Two old things...nice.</td>', 'I don''t think she''s going to get very far! Two old things...nice.', '2007-11-04 10:00:35.000000', NULL, 1),
(4220552, 606123, 77196, '<td valign="top">Hmmm... Less than 10 years old - maybe that''s an age in Motorcycle years. Too blurry and overprocessed for me.</td>', 'Hmmm... Less than 10 years old - maybe that''s an age in Motorcycle years. Too blurry and overprocessed for me.', '2007-11-04 15:27:42.000000', NULL, 1),
(4220695, 606123, 79141, '<td valign="top">i''m sure you were trying to capture the effect of speed  but really it looks more like an out of focus image  if you could had gotten the bike sharper  then i''d have given a higher score</td>', 'i''m sure you were trying to capture the effect of speed  but really it looks more like an out of focus image  if you could had gotten the bike sharper  then i''d have given a higher score', '2007-11-04 17:26:43.000000', NULL, 1),
(4220700, 605828, 79141, '<td valign="top">something about this i like  cant put my finger on it  tho  :) great image</td>', 'something about this i like  cant put my finger on it  tho  :) great image', '2007-11-04 17:29:38.000000', NULL, 1),
(4220704, 606439, 79141, '<td valign="top">brilliant</td>', 'brilliant', '2007-11-04 17:31:06.000000', NULL, 1),
(4220738, 606619, 83313, '<td valign="top">I have one of these! A nicely lit shot of it. Lots of details showing.</td>', 'I have one of these! A nicely lit shot of it. Lots of details showing.', '2007-11-04 17:53:30.000000', NULL, 1),
(4220742, 606717, 83313, '<td valign="top">I like the lights. the overall shot seems just a touch skewed.</td>', 'I like the lights. the overall shot seems just a touch skewed.', '2007-11-04 17:54:16.000000', NULL, 1),
(4220744, 606777, 83313, '<td valign="top">Very nice portrait. your use of b/w really makes his beard stand out.</td>', 'Very nice portrait. your use of b/w really makes his beard stand out.', '2007-11-04 17:54:58.000000', NULL, 1),
(4220747, 606655, 83313, '<td valign="top">I''m afraid it just seems plain.</td>', 'I''m afraid it just seems plain.', '2007-11-04 17:55:30.000000', NULL, 1),
(4220749, 606589, 83313, '<td valign="top">Very bold use of colors. I like the detail of the brickwork. I wonder how a composition that was not as centered would have done for it, though.</td>', 'Very bold use of colors. I like the detail of the brickwork. I wonder how a composition that was not as centered would have done for it, though.', '2007-11-04 17:56:39.000000', NULL, 1),
(4220752, 606542, 83313, '<td valign="top">It does indeed look like faces. Good eye for detail.</td>', 'It does indeed look like faces. Good eye for detail.', '2007-11-04 17:57:14.000000', NULL, 1),
(4220756, 606722, 83313, '<td valign="top">Nice use of color. I would like to know how this was done in order to get this feel to the image.</td>', 'Nice use of color. I would like to know how this was done in order to get this feel to the image.', '2007-11-04 17:58:26.000000', NULL, 1),
(4220758, 605774, 83313, '<td valign="top">Nice old wood. I like it, but wonder if just a little more tweaking would have deepened the color of the wood some more and really made it jump out.</td>', 'Nice old wood. I like it, but wonder if just a little more tweaking would have deepened the color of the wood some more and really made it jump out.', '2007-11-04 17:59:31.000000', NULL, 1),
(4220761, 606636, 83313, '<td valign="top">The  doorknob appears to be the subject, but the composition draws my eye up past it to the cieling.</td>', 'The  doorknob appears to be the subject, but the composition draws my eye up past it to the cieling.', '2007-11-04 18:01:01.000000', NULL, 1),
(4220764, 606203, 83313, '<td valign="top">Nice take on the subject. Looks a little more like 1961, though.</td>', 'Nice take on the subject. Looks a little more like 1961, though.', '2007-11-04 18:02:59.000000', NULL, 1),
(4220766, 606666, 83313, '<td valign="top">Nice lighting, color, detail and subject. Not sure the composition is drawing me into it, though. My eye just lands at the bottom of the image and stays on the glasses.</td>', 'Nice lighting, color, detail and subject. Not sure the composition is drawing me into it, though. My eye just lands at the bottom of the image and stays on the glasses.', '2007-11-04 18:04:30.000000', NULL, 1),
(4220767, 606769, 83313, '<td valign="top">This really pops off the screen. Love the rusty trough. the water spout seems too centered, however.</td>', 'This really pops off the screen. Love the rusty trough. the water spout seems too centered, however.', '2007-11-04 18:05:35.000000', NULL, 1),
(4220769, 606638, 83313, '<td valign="top">Too much in the midtone shades. Some more tweaking of curves may have deepened the appearance and made them stand out more.</td>', 'Too much in the midtone shades. Some more tweaking of curves may have deepened the appearance and made them stand out more.', '2007-11-04 18:07:10.000000', NULL, 1),
(4220816, 606397, 65234, '<td valign="top">It''s so old it has to be propped, huh?  Great-looking tree with lots of character; the shot could use more contrast and maybe a shallower DOF to focus my eye better on the tree itself.  Backing up a bit or getting closer to the ground would be cool, too.</td>', 'It''s so old it has to be propped, huh?  Great-looking tree with lots of character; the shot could use more contrast and maybe a shallower DOF to focus my eye better on the tree itself.  Backing up a bit or getting closer to the ground would be cool, too.', '2007-11-04 18:40:17.000000', NULL, 1),
(4220828, 606272, 83313, '<td valign="top">Nice glow of the chrome, though I would have liked to see the whole car.</td>', 'Nice glow of the chrome, though I would have liked to see the whole car.', '2007-11-04 18:47:51.000000', NULL, 1),
(4220869, 605637, 83313, '<td valign="top">Nice lighting effects.</td>', 'Nice lighting effects.', '2007-11-04 19:26:14.000000', NULL, 1),
(4220870, 604825, 83313, '<td valign="top">The composition does not draw me through the image.</td>', 'The composition does not draw me through the image.', '2007-11-04 19:27:07.000000', NULL, 1),
(4220871, 606611, 83313, '<td valign="top">Nice woodtones</td>', 'Nice woodtones', '2007-11-04 19:27:38.000000', NULL, 1),
(4220874, 606550, 83313, '<td valign="top">Nice image, but i''m not sure what i am looking at.</td>', 'Nice image, but i''m not sure what i am looking at.', '2007-11-04 19:28:22.000000', NULL, 1),
(4220881, 604445, 83313, '<td valign="top">I suppose as a child of the 60''s, i''m old enough that I should know what these are, but I don''t.</td>', 'I suppose as a child of the 60''s, i''m old enough that I should know what these are, but I don''t.', '2007-11-04 19:29:44.000000', NULL, 1),
(4220882, 604468, 83313, '<td valign="top">Nice contrast of colors, but the extreme angle is causing a poor depth of field that takes away from it.</td>', 'Nice contrast of colors, but the extreme angle is causing a poor depth of field that takes away from it.', '2007-11-04 19:30:32.000000', NULL, 1),
(4220885, 605255, 83313, '<td valign="top">A nice urban abstract. Good composition, and rust is always in style.</td>', 'A nice urban abstract. Good composition, and rust is always in style.', '2007-11-04 19:31:32.000000', NULL, 1),
(4220889, 605880, 83313, '<td valign="top">good old, reliable rust. Nice.</td>', 'good old, reliable rust. Nice.', '2007-11-04 19:32:12.000000', NULL, 1),
(4220893, 606352, 83313, '<td valign="top">The chrome really stands out here. good composition, depth of fieled, use of sepia, etc...</td>', 'The chrome really stands out here. good composition, depth of fieled, use of sepia, etc...', '2007-11-04 19:33:32.000000', NULL, 1),
(4220895, 606594, 83313, '<td valign="top">looks like a halloween pic. I like the colors on the truck. Not sure about the crop, though, and the interior does not stand out.</td>', 'looks like a halloween pic. I like the colors on the truck. Not sure about the crop, though, and the interior does not stand out.', '2007-11-04 19:34:44.000000', NULL, 1),
(4220898, 605315, 83313, '<td valign="top">Nice texture on the building, seems too centered for me, though.</td>', 'Nice texture on the building, seems too centered for me, though.', '2007-11-04 19:35:41.000000', NULL, 1),
(4220900, 605510, 83313, '<td valign="top">Great framing. Looks like a scene out of a storybook. I found another fave.</td>', 'Great framing. Looks like a scene out of a storybook. I found another fave.', '2007-11-04 19:37:26.000000', NULL, 1),
(4220903, 605881, 83313, '<td valign="top">Simple, but good visual impact. I love to see pedestrian items done in a different way, and how much more pedestrian than a boot?</td>', 'Simple, but good visual impact. I love to see pedestrian items done in a different way, and how much more pedestrian than a boot?', '2007-11-04 19:38:53.000000', NULL, 1),
(4220915, 606448, 83313, '<td valign="top">Very interesting and fun.</td>', 'Very interesting and fun.', '2007-11-04 19:44:40.000000', NULL, 1),
(4220919, 606702, 83313, '<td valign="top">A great portrait of him, but he didn''t bring a second coffee for me.</td>', 'A great portrait of him, but he didn''t bring a second coffee for me.', '2007-11-04 19:45:50.000000', NULL, 1),
(4220921, 605594, 83313, '<td valign="top">Looks like a weird face screaming. Very creative.</td>', 'Looks like a weird face screaming. Very creative.', '2007-11-04 19:46:36.000000', NULL, 1),
(4220923, 606459, 83313, '<td valign="top">Yuck. But that''s certainly the intended reaction, so take that as a successful shot!</td>', 'Yuck. But that''s certainly the intended reaction, so take that as a successful shot!', '2007-11-04 19:47:30.000000', NULL, 1),
(4220925, 606827, 83313, '<td valign="top">Nice b/w usage. I''m not sure if the centered subject does well for this or not. I would not mind seeing some of your other shots of this subject.</td>', 'Nice b/w usage. I''m not sure if the centered subject does well for this or not. I would not mind seeing some of your other shots of this subject.', '2007-11-04 19:48:36.000000', NULL, 1),
(4220929, 605324, 83313, '<td valign="top">loud and colorful, but that''s graffiti, right?</td>', 'loud and colorful, but that''s graffiti, right?', '2007-11-04 19:49:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4220931, 606701, 83313, '<td valign="top">I like the rusted green paint. perspective looks slightly distorted.</td>', 'I like the rusted green paint. perspective looks slightly distorted.', '2007-11-04 19:50:42.000000', NULL, 1),
(4220932, 605642, 83313, '<td valign="top">This is great. Somehow the mountain and rainbow seem out of place with the building.</td>', 'This is great. Somehow the mountain and rainbow seem out of place with the building.', '2007-11-04 19:51:47.000000', NULL, 1),
(4220935, 606647, 83313, '<td valign="top">A good view of something common.</td>', 'A good view of something common.', '2007-11-04 19:52:46.000000', NULL, 1),
(4220936, 606036, 83313, '<td valign="top">Very well done. Good clarity and composition.</td>', 'Very well done. Good clarity and composition.', '2007-11-04 19:53:23.000000', NULL, 1),
(4220976, 606763, 74588, '<td valign="top">r4ealy?   6</td>', 'r4ealy?   6', '2007-11-04 20:20:49.000000', NULL, 1),
(4220981, 606203, 74588, '<td valign="top">perfect     10</td>', 'perfect     10', '2007-11-04 20:21:48.000000', NULL, 1),
(4220992, 606802, 74588, '<td valign="top">aint it so    8</td>', 'aint it so    8', '2007-11-04 20:24:42.000000', NULL, 1),
(4221529, 605839, 86081, '<td valign="top">Nice alliteration, sexy.</td>', 'Nice alliteration, sexy.', '2007-11-04 23:58:43.000000', NULL, 1),
(4222480, 606715, 69388, '<td valign="top">Great image! I love the light and the painterly grain treatment is delightful!</td>', 'Great image! I love the light and the painterly grain treatment is delightful!', '2007-11-05 09:00:34.000000', NULL, 1),
