(4226892, 606728, 14620, '<td valign="top">I didn''t hate it. :)</td>', 'I didn''t hate it. :)', '2007-11-07 00:14:26.000000', NULL, 0),
(4226895, 606757, 30861, '<td valign="top">LOL. Great shot! I am a native of San Diego and grew up on Point Loma. I shot this danged thing a ton of times. It''s actually called the "Old Spanish Lighthouse", or used to be, and we got a laugh out of that because it is neither Spanish nor particularly old. It was actually a mistake, an almost useless lighthouse because it is so high the coastal fog usually obliterated it; so the built the one down on the beach not all that long after this one went up.<br/> <br/>Congrats on blue!</td>', 'LOL. Great shot! I am a native of San Diego and grew up on Point Loma. I shot this danged thing a ton of times. It''s actually called the "Old Spanish Lighthouse", or used to be, and we got a laugh out of that because it is neither Spanish nor particularly old. It was actually a mistake, an almost useless lighthouse because it is so high the coastal fog usually obliterated it; so the built the one down on the beach not all that long after this one went up. Congrats on blue!', '2007-11-07 00:14:44.000000', NULL, 0),
(4226896, 606757, 40718, '<td valign="top">First ribbon and a blue!  That''s some sweet, sweet action!  Your score blew the rest of us away.</td>', 'First ribbon and a blue!  That''s some sweet, sweet action!  Your score blew the rest of us away.', '2007-11-07 00:14:45.000000', NULL, 0),
(4226898, 606757, 60862, '<td valign="top">Congrats on a beautiful shot, your first ribbon, and your new personal best!</td>', 'Congrats on a beautiful shot, your first ribbon, and your new personal best!', '2007-11-07 00:14:50.000000', NULL, 0),
(4226903, 605556, 14986, '<td valign="top">I love how the warm tones of the rust and truck contrast with the blues and the snow of the background.  I wish the front of the truck wasn''t quite so dark, but I still like this alot.</td>', 'I love how the warm tones of the rust and truck contrast with the blues and the snow of the background.  I wish the front of the truck wasn''t quite so dark, but I still like this alot.', '2007-11-07 00:15:18.000000', NULL, 0),
(4226904, 606715, 50641, '<td valign="top">excellent histogram!  this dude is priceless! and the lighting and processing increase his intrigue.  you should ask him to pose on the bridge in the fog ;-)</td>', 'excellent histogram!  this dude is priceless! and the lighting and processing increase his intrigue.  you should ask him to pose on the bridge in the fog ;-)', '2007-11-07 00:15:21.000000', NULL, 0),
