(4608650, 604687, 89424, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by rhodanig:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by DavidLopez:</b></div><hr/><i> Maybe if it said commodore 64 or magnavox even atari but gameboy? Nothing old about that. </i></td></tr></table> <br/> <br/>You can tell from my commentary that I was trying to make a statement about the rapid obsolescence of tech gear.  A Commodore 64 would have totally missed the point.  Guess my intent did not come through in the photograph. </i></td></tr></table> <br/> <br/>I can understand that view becuase technically all of those are old. It should say XBOX 360, PS3, Gameboy DS, Blueray and probably Wii.</td>', 'Originally posted by rhodanig: Originally posted by DavidLopez: Maybe if it said commodore 64 or magnavox even atari but gameboy? Nothing old about that.   You can tell from my commentary that I was trying to make a statement about the rapid obsolescence of tech gear.  A Commodore 64 would have totally missed the point.  Guess my intent did not come through in the photograph.   I can understand that view becuase technically all of those are old. It should say XBOX 360, PS3, Gameboy DS, Blueray and probably Wii.', '2008-04-02 21:07:14.000000', NULL, 0),
(4625091, 606154, 18349, '<td valign="top">God puts angels on our paths along the way through daily life...we are all blessed to have at least one among us on DPC.  :)</td>', 'God puts angels on our paths along the way through daily life...we are all blessed to have at least one among us on DPC.  :)', '2008-04-09 00:04:53.000000', NULL, 0),
