(4839477, 606728, 82817, '<td valign="top">I am impressed with the outcome of this image. Wonderful.</td>', 'I am impressed with the outcome of this image. Wonderful.', '2008-07-22 23:12:37.000000', NULL, 0),
(4895719, 606835, 28742, '<td valign="top">LOL!</td>', 'LOL!', '2008-08-18 15:45:33.000000', NULL, 0),
(4917049, 606835, 69008, '<td valign="top">I am looking at this and trying to think of a POV or camera angle that would be different enough to make the subject look more interesting. <br/>It looks like it was an overcast day, so it has very little shadow. <br/>I connect with the shot because I lived in West Palm Beach Fl in one just about like it, same color, same interior layout, for about 6 years during my 20''s. I was single, working construction 5 days a week and playing music 3 nights a week during that time    Ahhh, Happy memories. :  )</td>', 'I am looking at this and trying to think of a POV or camera angle that would be different enough to make the subject look more interesting. It looks like it was an overcast day, so it has very little shadow. I connect with the shot because I lived in West Palm Beach Fl in one just about like it, same color, same interior layout, for about 6 years during my 20''s. I was single, working construction 5 days a week and playing music 3 nights a week during that time    Ahhh, Happy memories. :  )', '2008-08-28 01:08:36.000000', NULL, 0),
(4943110, 606672, 3936, '<td valign="top">Very nice IR photo.  The infrared really fits here.  Too many times it seems that people use IR as a gimmick.  This really helps set the mood for this old place.  I agree with your choice.  Of the three, the brownish sky fit the best.</td>', 'Very nice IR photo.  The infrared really fits here.  Too many times it seems that people use IR as a gimmick.  This really helps set the mood for this old place.  I agree with your choice.  Of the three, the brownish sky fit the best.', '2008-09-08 21:06:05.000000', NULL, 0),
(4955461, 606633, 48228, '<td valign="top">One of my all time favorite ''emotive'' portraits at DPC that''s for sure.....</td>', 'One of my all time favorite ''emotive'' portraits at DPC that''s for sure.....', '2008-09-15 01:10:35.000000', NULL, 0),
